async function add(a: int, b: int): int { return a + b; }
async function greet(name: string): string { return "hi-" + name; }
async function flag(): boolean { return true; }
export async function test(): string {
  let x: int = await add(2, 3);
  let y: int = await add(x, 5);
  let b: boolean = await flag();
  if (y === 10 && b) { return await greet("jvm"); }
  return "bad";
}

import * as console from "std/console"
async function tick(tag: string): int { console.log(tag); return 1; }
export async function test(): int {
  await tick("first");
  await tick("second");
  await tick("third");
  return 3;
}

async function flag(): boolean { return true; }
async function noop(): null { return; }
export async function test(): boolean {
  await noop();
  let b: boolean = await flag();
  return b;
}

async function innermost(): int { return 1 / 0; }
async function mid(): int { return await innermost(); }
export async function test(): int { return await mid(); }

async function inner(): int { return 7; }
async function outer(x: int): int { return x + 1; }
export async function test(): int { return await outer(await inner()); }

async function flag(): boolean { return true; }
export async function test(): int {
  if (await flag()) { return 1; }
  return 0;
}

async function value(): int { return 6; }
export async function test(): int {
  let f: async () => int = value;
  return await f();
}

async function plus1(x: int): int { return x + 1; }
async function apply(cb: async (x: int) => int, v: int): int { return await cb(v); }
export async function test(): int { return await apply(plus1, 6); }

async function a(): string { return "a"; }
async function b(): string { return "b"; }
export async function test(): string {
  let f: async () => string = a;
  let s: string = await f();
  f = b;
  let t: string = await f();
  return s + t;
}

